// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: the caller address and a timestamp to warp to
    function testFuzz_property(address caller, uint256 ts) public {
        // keep caller non-zero
        vm.assume(caller != address(0));
        // keep timestamp in reasonable range and non-decreasing
        ts = bound(ts, 1, type(uint64).max);

        // Arrange: give caller some ETH to send
        uint256 sendAmt = 10 ether;
        vm.deal(caller, sendAmt);

        // set block timestamp to fuzzed ts
        vm.warp(ts);

        // Act: have caller call the fallback with exactly 10 ether
        vm.prank(caller);
        bool ok;
        try c.f{value: sendAmt}() {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: on the correct contract, calling fallback with exactly 10 ether
        // must succeed (ok == true) and must set pastBlockTime to the current block.timestamp.
        // We observe this via the public getter pastBlockTime().
        // Single assertion: either the call reverted (ok == false) OR the stored pastBlockTime equals ts.
        // For the reference contract, the call with 10 ether should succeed and pastBlockTime == ts for all inputs;
        // the mutant requiring 11 ether will cause the call to revert (ok == false) or not update pastBlockTime.
        assertTrue(!ok || c.pastBlockTime() == ts);
    }
}

