pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the sender and the amount; the distinguishing amount is 10 ether but we do not hard-code it
    function testFuzz_property(address sender, uint256 sendAmt) public {
        // keep sender as a regular EOA (non-zero) and bound sendAmt to a reasonable range up to 20 ether
        vm.assume(sender != address(0));
        uint256 amt = bound(sendAmt, 0, 20 ether);

        // set block timestamp to a known value and ensure it's greater than any prior stored pastBlockTime (initially 0)
        vm.warp(1 days);

        // fund the sender so it can send ether
        vm.deal(sender, amt);

        // perform the call from the fuzzed sender sending amt wei to the fallback
        vm.prank(sender);
        // use low-level call to invoke fallback with value
        (bool ok,) = address(c).call{value: amt}("");
        // After the call, read the public getter pastBlockTime
        uint256 stored = c.pastBlockTime();

        // General rule to assert: If the call succeeded and the amount sent equals 10 ether,
        // then the reference contract always updated pastBlockTime to current block.timestamp (1 day),
        // so stored == block.timestamp. The mutant requiring 11 ether will make the call revert for 10 ether
        // and thus either ok==false or stored != block.timestamp. We express the universal rule as a single assertion:
        // For this fuzz input, if the call succeeded then (amt != 10 ether) OR stored == block.timestamp.
        // This holds for the reference implementation for all inputs (calls with amt==10 ether succeed and update),
        // but the mutant breaks it for some input (amt==10 ether: call will revert or stored won't be updated).
        assertTrue(!ok || amt != 10 ether || stored == block.timestamp);
    }
}

