pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters: a caller address and a timestamp to warp to, and a block number offset.
    // The rule: after a successful fallback call sending exactly 10 ether, c.pastBlockTime() equals block.timestamp.
    // The mutant inverts the comparison and will cause the assignment to be skipped for inputs where block.timestamp is not < pastBlockTime.
    function testFuzz_property(address actor, uint256 warpTs, uint256 rollOffset) public {
        // keep actor non-zero
        vm.assume(actor != address(0));

        // bound warpTs to a reasonable future/past so fuzzer can explore different relations
        warpTs = bound(warpTs, 1, type(uint256).max - 1000);
        // bound rollOffset to a modest range to vary block.number
        rollOffset = bound(rollOffset, 0, 1000);

        // fund the actor so they can send 10 ether
        vm.deal(actor, 20 ether);

        // set initial pastBlockTime to something: call once to set it to current timestamp
        // warp to a baseline time and call fallback to initialize pastBlockTime
        vm.warp(1);
        vm.prank(actor);
        c.f{value: 10 ether}(); // first call sets pastBlockTime = 1 in reference

        // now set up adversarial timing for the fuzzed call
        // warp to fuzzed timestamp and advance blocks by rollOffset
        vm.warp(warpTs);
        // ensure block.number changes; roll to current + rollOffset
        uint256 targetBlock = block.number + rollOffset;
        vm.roll(targetBlock);

        // perform the fuzzed call sending exactly 10 ether
        vm.prank(actor);
        // perform call and ignore revert (we only care about state when it succeeds);
        // but fallback requires msg.value == 10 ether so it should succeed
        c.f{value: 10 ether}();

        // Single assertion: in the correct contract, after a successful fallback call that accepted 10 ether,
        // pastBlockTime must equal the current block.timestamp for ALL admissible inputs.
        // The mutant that inverts the comparison will fail this for some inputs where the require blocks assignment.
        assertTrue(c.pastBlockTime() == block.timestamp);
    }
}

