pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: a prior time to set pastBlockTime (as uint256) and a block timestamp delta
    function testFuzz_property(uint256 priorPastBlockTime, uint256 warpDelta) public {
        // Keep inputs wide but avoid absurd warp causing overflow when adding
        priorPastBlockTime = bound(priorPastBlockTime, 0, type(uint256).max - 1 days);
        warpDelta = bound(warpDelta, 0, 365 days);

        // Arrange: set c.pastBlockTime to a fuzzed prior value by simulating a call that sets it.
        // To do that, we need to make a call to fallback that will succeed in the reference:
        // It requires msg.value == 10 ether and block.timestamp > pastBlockTime. We'll ensure that
        // by first warping to priorPastBlockTime - 1 (so block.timestamp > 0) and then calling to set
        // pastBlockTime to that prior value by warping and making another call. We'll perform two setup steps:

        // Step A: ensure an initial block timestamp lower than priorPastBlockTime so we can set pastBlockTime to priorPastBlockTime.
        // Warp to a time slightly before priorPastBlockTime.
        vm.warp(priorPastBlockTime == 0 ? 0 : priorPastBlockTime - 1);

        // Fund and call to set pastBlockTime to the current timestamp (which is priorPastBlockTime - 1)
        address sender = address(0xBEEF);
        vm.deal(sender, 20 ether);
        vm.prank(sender);
        // first call: this will set pastBlockTime = block.timestamp = priorPastBlockTime - 1
        c.f{value: 10 ether}();

        // Step B: now warp forward so that a second call can set pastBlockTime to the fuzzed priorPastBlockTime value.
        vm.warp(priorPastBlockTime);
        vm.prank(sender);
        c.f{value: 10 ether}();
        // Now c.pastBlockTime == priorPastBlockTime in the reference.

        // Now decide the next call time: warp to priorPastBlockTime + warpDelta and perform the deciding call.
        uint256 decidingTime = priorPastBlockTime + warpDelta;
        // Keep within reasonable bounds
        vm.warp(decidingTime);

        // Ensure the caller has funds and call
        address caller = address(0xCAFE);
        vm.deal(caller, 20 ether);
        vm.prank(caller);

        // Execute the deciding call which should set pastBlockTime = block.timestamp in the reference for any inputs
        c.f{value: 10 ether}();

        // Assert the universal property: after this call, c.pastBlockTime equals the current block.timestamp
        // This holds for the reference for all admissible inputs; the mutant that inverts the timestamp comparison
        // will fail for some inputs (e.g., when block.timestamp is not greater than priorPastBlockTime)
        assertTrue(c.pastBlockTime() == block.timestamp);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz parameters: prevTime is used to set an initial pastBlockTime (via calling fallback in a preparatory step);
    // warpTime is the time at which we perform the decisive call; caller is the address that will send the ether.
    function testFuzz_property(uint256 prevTime, uint256 warpTime, address caller) public {
        // keep caller non-zero
        vm.assume(caller != address(0));

        // Bind times to reasonable 64-bit unix seconds to avoid extreme values
        prevTime = bound(prevTime, 0, type(uint64).max);
        warpTime = bound(warpTime, 0, type(uint64).max);

        // Prepare the contract so that pastBlockTime == prevTime by forcing a successful fallback call at that time.
        // To call fallback, send exactly 10 ether from a funded address.
        vm.deal(caller, 20 ether);

        // set the chain time and do a prior call to initialize pastBlockTime
        vm.warp(prevTime);
        vm.prank(caller);
        // send exactly 10 ether to fallback
        (bool ok1, ) = address(c).call{value: 10 ether}("");
        // require the prep call to have succeeded on the reference contract; if it reverted we cannot proceed
        // but we let the fuzzer explore inputs where it might revert (ok1 false)

        // Now perform the decisive call at warpTime from another (still fuzzed) caller address
        vm.warp(warpTime);
        vm.prank(caller);
        (bool ok2, ) = address(c).call{value: 10 ether}("");

        // The universal property: whenever a call sending exactly 10 ether to fallback completes successfully,
        // the reference contract sets pastBlockTime == block.timestamp (the current chain time). We assert that
        // if the call succeeded, c.pastBlockTime() equals the current block.timestamp.
        // This will be true for the reference; the mutant that inverts the timestamp check will allow some inputs
        // (combinations of prevTime and warpTime) where ok2 is true but pastBlockTime != warpTime, so the test will fail.
        if (ok2) {
            assertTrue(c.pastBlockTime() == warpTime);
        } else {
            // if the call reverted, we still assert the universal property vacuously by checking that the call did indeed revert
            // (i.e., ok2 == false). This branch is needed so the single assertion always reads c's state when the call succeeded.
            assertTrue(ok2 == false);
        }
    }
}
